/* Measured transfer tools. Existing reaction and liquid-transfer engines remain authoritative. */
const transferIndicatorTypes=new Set(['phenolphthalein','methylOrange','indicator','hardnessIndicator','starch','cabbage']);
const transferSolidStocks=[
 {name:'Sodium chloride (solid)',formula:'NaCl',type:'chloride',M:58.4428},
 {name:'Sodium carbonate (anhydrous solid)',formula:'Na₂CO₃',type:'carbonate',M:105.9888},
 {name:'Sodium bicarbonate (solid)',formula:'NaHCO₃',type:'bicarbonate',M:84.0066},
 {name:'Glucose (anhydrous solid)',formula:'C₆H₁₂O₆',type:'glucose',M:180.156},
 {name:'Sucrose (solid)',formula:'C₁₂H₂₂O₁₁',type:'sucrose',M:342.296},
 {name:'Sodium hydroxide (assumed-pure reference solid)',formula:'NaOH',type:'base',M:39.997},
 {name:'Potassium hydrogen phthalate (KHP reference solid)',formula:'KHC₈H₄O₄',type:'khp',M:204.2212}
];
let transferLastReceiverId=null;
let transferLastSolidSourceId=null,transferPickingSolidFor=null;
function transferBenchSolidSources(tool){return apparatus.flatMap(a=>a.id===tool.id||a.type==='spatula'||Number(a.volume)>1e-12?[]:(a.contents||[]).flatMap((c,index)=>transferDry(c)?[{a,c,index,value:`dry:${a.id}:${index}`}]:[]));}
function transferSpatulaSource(a){if(a.toolSolidMode==='stock')return {stock:transferSolidStocks[Number(a.toolSolidStock??0)]};const rows=transferBenchSolidSources(a),row=rows.find(x=>x.value===a.toolSolidSource)||rows.find(x=>x.a.id===transferLastSolidSourceId)||rows[0];return row||null;}
function transferSpatulaPanel(a,mass,receiver){const rows=transferBenchSolidSources(a),source=transferSpatulaSource(a),stock=a.toolSolidMode==='stock',options=stock?transferSolidStocks.map((s,i)=>`<option value="stock:${i}" ${Number(a.toolSolidStock??0)===i?'selected':''}>${esc(s.name)} · stock bottle</option>`).join(''):rows.map(row=>`<option value="${row.value}" ${source?.value===row.value?'selected':''}>${esc(benchVesselLabel(row.a))} · ${esc(row.c.reagent)} · ${Number(row.c.mass).toPrecision(5)} g available</option>`).join(''),load=source?.c?Math.min(.1,Number(source.c.mass)):.1;
 if(mass>0){const origin=apparatus.find(v=>v.id===a.toolSolidOriginId),remaining=(origin?.contents||[]).filter(c=>transferDry(c)&&c.reagent===a.contents[0]?.reagent&&c.formula===a.contents[0]?.formula).reduce((sum,c)=>sum+Number(c.mass),0);return `<p><b>Loaded from ${origin?esc(benchVesselLabel(origin)):a.toolSolidOriginId?'previous source vessel':'stock bottle'}</b></p><p class="tool-inventory">${esc(a.contents.map(c=>c.reagent).join(' + '))} · <b>${mass.toPrecision(5)} g on the spatula</b></p>${origin?`<p>Remaining in ${esc(benchVesselLabel(origin))}: <b>${remaining.toPrecision(5)} g</b>.</p>`:''}${receiver}<label>Mass to transfer (g)<input id="toolTransferMass" type="number" min="0.000001" max="${mass}" step="any" value="${Number(mass.toPrecision(8))}"></label><button type="button" class="btn small" data-transfer-tool="spatula-transfer">Transfer measured solid</button><small>Deliver all or part of the loaded solid. The receiving vessel gains that mass and the spatula loses the same mass. Empty the spatula before choosing a different solid source.</small>`;}
 return `<p>Take a weighed portion from a solid already in a vessel on this bench, then choose a different receiving vessel.</p><label for="toolSolidMode">Source location</label><select id="toolSolidMode" ${mass>0?'disabled':''}><option value="bench" ${!stock?'selected':''}>Vessels on this bench</option><option value="stock" ${stock?'selected':''}>Stock bottle (new material)</option></select><label for="toolSource">${stock?'Stock bottle':'Source vessel and solid'}</label><select id="toolSource" ${mass>0?'disabled':''}>${options||'<option value="">No dry solid in a bench vessel</option>'}</select>${!stock?`<button type="button" class="btn secondary small" data-transfer-tool="pick-solid-source" ${mass>0?'disabled':''}>${transferPickingSolidFor===a.id?'Cancel source selection':'Pick source on bench'}</button><p class="tool-inventory">${source?.c?`${esc(benchVesselLabel(source.a))} contains ${Number(source.c.mass).toPrecision(5)} g ${esc(source.c.reagent)}.`:'Select a beaker containing a weighed dry solid. You can add one from its “Add weighed dry solid” controls. Dissolved solutes and wet precipitates cannot be scooped out as dry powder.'}</p>`:''}<label>Mass to load (g)<input id="toolLoadMass" type="number" min="0.000001" ${source?.c?`max="${source.c.mass}"`:''} step="any" value="${load}"></label><button type="button" class="btn soft small" data-transfer-tool="load-spatula" ${!source||mass>0?'disabled':''}>${stock?'Load weighed solid from stock':'Load from source vessel'}</button><p class="tool-inventory">${a.contents?.length?esc(a.contents.map(c=>c.reagent).join(' + ')):'Clean spatula'} · ${mass.toPrecision(5)} g loaded</p>${receiver}<label>Mass to transfer (g)<input id="toolTransferMass" type="number" min="0.000001" step="any" value="${mass>0?Number(mass.toPrecision(8)):.1}"></label><button type="button" class="btn small" data-transfer-tool="spatula-transfer" ${mass>0?'':'disabled'}>Transfer measured solid</button><small>Loading reduces the source vessel’s actual solid mass. Delivery reduces the spatula’s load and adds the same material to the receiver. Use an attached funnel for a volumetric flask.</small>`;
}
function transferBenchSolidControls(a){if(!acceptsSolid(a.type))return '';return `<details class="tool-preparation"><summary>Add weighed dry solid</summary><label for="benchSolidStock">Reference solid</label><select id="benchSolidStock">${transferSolidStocks.map((s,i)=>`<option value="${i}">${esc(s.name)}</option>`).join('')}</select><label for="benchSolidMass">Weighed mass (g)</label><input id="benchSolidMass" type="number" min="0.000001" step="any" value="1"><button type="button" class="btn soft small" data-transfer-tool="place-bench-solid">Place weighed solid in this vessel</button><small>This adds new material from a stock bottle. Select the spatula afterwards to transfer part of this vessel’s measured inventory.</small></details>`;}
function transferMakeSolid(s,mass){return {reagent:s.name,formula:s.formula,type:s.type,color:'#f7faf8',volume:0,mass,solidStock:true,solidMolarMass:typeof ttFormulaMass==='function'?ttFormulaMass(s.formula)?.mass||s.M:s.M,solidDissolved:false};}
function transferAddDryItem(target,moved){const same=target.contents.find(c=>transferDry(c)&&c.reagent===moved.reagent&&c.formula===moved.formula&&c.type===moved.type&&c.solidMolarMass===moved.solidMolarMass&&!!c.solidStock===!!moved.solidStock);if(same)same.mass=Number((Number(same.mass)+Number(moved.mass)).toPrecision(14));else target.contents.push(moved);}
function transferToolIsVessel(a){return a&&acceptsLiquid(a.type)&&!['dropper','burette','volumetricPipette','graduatedPipette','washBottle'].includes(a.type);}
function transferDry(c){return Number(c.mass)>0&&!(Number(c.volume)>0)&&!c.solidDissolved;}
function transferCap(a){return Number(equipment.find(x=>x[0]===a?.type)?.[3])||0;}
function transferOptions(list,chosen){return list.map(a=>{const dry=(a.contents||[]).filter(transferDry).reduce((sum,c)=>sum+Number(c.mass),0),amount=dry>0&&!(Number(a.volume)>0)?' · '+dry.toPrecision(5)+' g solid':transferCap(a)?' · '+Number(a.volume||0).toFixed(2)+' / '+transferCap(a)+' mL':'';return `<option value="${a.id}" ${chosen===a.id?'selected':''}>${esc(benchVesselLabel(a))}${amount}</option>`;}).join('');}
function transferChosenReceiver(a,list){return list.some(x=>x.id===a.toolReceiverId)?a.toolReceiverId:list.some(x=>x.id===transferLastReceiverId)?transferLastReceiverId:list.find(x=>a.type==='spatula'&&acceptsSolid(x.type)&&!x.contents?.length)?.id||list.find(x=>a.type==='spatula'&&acceptsSolid(x.type)&&!(Number(x.volume)>1e-12))?.id||list.find(x=>x.type==='volumetricFlask')?.id||list[0]?.id||'';}
function transferDrySources(tool,includeStock=false,excludeId=null){let rows=includeStock?transferSolidStocks.map((s,i)=>`<option value="stock:${i}">${esc(s.name)} · stock bottle</option>`):[];for(const a of apparatus){if(a.id===tool.id||a.id===excludeId||Number(a.volume)>1e-12)continue;for(const [i,c]of (a.contents||[]).entries())if(transferDry(c))rows.push(`<option value="dry:${a.id}:${i}">${esc(benchVesselLabel(a))} · ${esc(c.reagent)} · ${Number(c.mass).toFixed(4)} g</option>`);}return rows.join('');}
function transferSourceRecord(value){const [kind,id,index]=String(value).split(':');if(kind==='stock'){const s=transferSolidStocks[Number(id)];if(!s)return null;return {stock:s};}const a=apparatus.find(x=>x.id===id),c=a?.contents?.[Number(index)];return kind==='dry'&&a&&c&&transferDry(c)?{a,c,index:Number(index)}:null;}
function transferToolPopup(a){if(!['dropper','spatula','glassFunnel','volumetricPipette','graduatedPipette','washBottle','glassRod'].includes(a?.type))return null;if(benchPopupHiddenFor===a.id)return '';
 if(a.type==='spatula'&&transferPickingSolidFor===a.id)return `<section class="bench-apparatus-popup simple-apparatus-popup transfer-tool-popup tool-pick-popup" role="dialog" aria-label="Pick solid source on bench" style="right:8px;left:auto;top:8px"><header class="apparatus-popup-head"><b>Choose source vessel</b><button type="button" data-transfer-tool="pick-solid-source" aria-label="Cancel source selection">×</button></header><div class="apparatus-popup-content"><p id="toolStatus" role="status">Click the beaker or vessel containing the dry solid. Empty vessels, solutions and wet precipitates cannot supply a dry scoop.</p></div></section>`;
 const solidSourceId=a.type==='spatula'?(a.contents?.length?a.toolSolidOriginId:transferSpatulaSource(a)?.a?.id):null;const receivers=apparatus.filter(x=>x.id!==a.id&&x.id!==solidSourceId&&(a.type==='spatula'?(acceptsSolid(x.type)||x.type==='volumetricFlask'):transferToolIsVessel(x))),chosen=transferChosenReceiver(a,receivers),receiver=`<label for="toolReceiver">Destination vessel</label><select id="toolReceiver">${transferOptions(receivers,chosen)||'<option value="">Add a suitable vessel first</option>'}</select><button type="button" class="btn secondary small" data-transfer-tool="inspect-receiver">Inspect destination vessel</button>`,mass=(a.contents||[]).reduce((s,c)=>s+(Number(c.mass)||0),0),note=a.toolMessage||'Select the measured amount and a destination before transferring.';
 let body='';
 if(a.type==='dropper'){const stocks=reagents.map((r,i)=>({r,i})).filter(x=>transferIndicatorTypes.has(x.r[2]));body=`<p>Load an indicator, then dispense drops into a vessel. The dropper holds only what you load.</p><label for="toolIndicator">Indicator stock</label><select id="toolIndicator">${stocks.map(({r,i})=>`<option value="${i}" ${Number(a.toolIndicator??reagents.findIndex(r=>r[2]==='phenolphthalein'))===i?'selected':''}>${esc(r[0])}</option>`).join('')}</select><div class="tool-fields"><label>Load volume (mL)<input id="toolLoadVolume" type="number" min="0.01" max="${transferCap(a)}" step="0.01" value="1"></label><button type="button" class="btn soft small" data-transfer-tool="load-dropper">Load dropper</button></div><p class="tool-inventory">${a.contents?.length?esc(a.contents.map(c=>c.reagent).join(' + ')):'Clean, empty dropper'} · ${Number(a.volume||0).toFixed(2)} mL available</p>${receiver}<div class="tool-fields"><label>Drops<input id="toolDrops" type="number" min="1" step="1" value="${a.toolDrops??1}"></label><label>Assumed mL / drop<input id="toolDropSize" type="number" min="0.01" max="0.1" step="0.01" value="${a.toolDropSize??.05}"></label></div><small>Default: 1 drop ≈ 0.05 mL. Real drops vary; this is an editable teaching assumption, not a calibrated pipette.</small><button type="button" class="btn small" data-transfer-tool="dispense">Dispense drops</button>`;}
 if(a.type==='spatula')body=transferSpatulaPanel(a,mass,receiver);
 if(a.type==='glassFunnel'){const target=apparatus.find(x=>x.id===a.funnelTargetId),liquids=apparatus.filter(x=>x.id!==target?.id&&x.id!==a.id&&acceptsLiquid(x.type)&&x.volume>0);body=`<p>A glass funnel guides material into a receiving vessel; it does not store liquid. Attach it to an upright flask first.</p>${receiver}<div class="tool-fields"><button type="button" class="btn soft small" data-transfer-tool="attach">Attach funnel</button><button type="button" class="btn secondary small" data-transfer-tool="detach">Detach</button></div><p class="tool-inventory">${target?'Attached to '+esc(benchVesselLabel(target)):'Not attached'}</p><label for="toolSource">Transfer from</label><select id="toolSource"><option value="">Choose a measured source</option>${liquids.map(x=>`<option value="liq:${x.id}">${esc(benchVesselLabel(x))} · ${Number(x.volume).toFixed(2)} mL liquid</option>`).join('')}${transferDrySources(a,false,target?.id)||''}</select><label><span id="toolAmountLabel">Measured amount (mL for liquid; g for solid)</span><input id="toolFunnelAmount" type="number" min="0.000001" step="any" value="1"></label><button type="button" class="btn small" data-transfer-tool="funnel-transfer">Transfer through funnel</button><small>Capacity is checked on the receiving flask. Remove the funnel after transfer, then dissolve the solid and make up to the calibration mark.</small>`;}
 if(['volumetricPipette','graduatedPipette'].includes(a.type)){const fixed=a.type==='volumetricPipette',sources=apparatus.filter(x=>x.id!==a.id&&transferToolIsVessel(x)&&x.volume>0);body=`<p>${fixed?'Single-mark volumetric pipette: fill to its calibration mark and deliver the full rated aliquot.':'Graduated pipette: load liquid from a source vessel, then deliver a measured portion.'}</p><label for="toolPipetteSource">Source solution</label><select id="toolPipetteSource">${transferOptions(sources,a.toolPipetteSource)||'<option value="">Add a solution to a vessel first</option>'}</select>${fixed?`<p class="tool-inventory">Rated aliquot: ${transferCap(a)} mL</p>`:'<label>Volume to load (mL)<input id="toolPipetteLoad" type="number" min="0.000001" step="any" value="5"></label>'}<button type="button" class="btn soft small" data-transfer-tool="pipette-load">${fixed?'Fill pipette to calibration mark':'Load measured liquid'}</button><p class="tool-inventory">${Number(a.volume||0).toPrecision(5)} mL loaded</p>${receiver}${fixed?'':'<label>Volume to deliver (mL)<input id="toolPipetteDose" type="number" min="0.000001" step="any" value="1"></label>'}<button type="button" class="btn small" data-transfer-tool="pipette-deliver">${fixed?'Deliver calibrated aliquot':'Deliver measured volume'}</button>`;}
 if(a.type==='washBottle')body=`<p>Distilled water only. Rinsing adds water to the destination and dilutes its contents; this bottle is not a calibrated volumetric instrument.</p><label>Water to load (mL)<input id="toolWaterLoad" type="number" min="0.01" max="${transferCap(a)}" step="any" value="100"></label><button type="button" class="btn soft small" data-transfer-tool="water-load">Load distilled water</button><p class="tool-inventory">${Number(a.volume||0).toPrecision(5)} mL available</p>${receiver}<label>Water delivered (mL)<input id="toolWaterDose" type="number" min="0.000001" step="any" value="5"></label><button type="button" class="btn small" data-transfer-tool="water-rinse">Rinse / add water</button>`;
 if(a.type==='glassRod'){const sources=apparatus.filter(x=>transferToolIsVessel(x)&&x.volume>0);body=`<p>Use the rod to guide liquid from a source vessel into a receiver, or stir the receiver to mix its contents.</p><label for="toolRodSource">Source vessel</label><select id="toolRodSource">${transferOptions(sources,a.toolRodSource)}</select>${receiver}<label>Volume to guide (mL)<input id="toolRodAmount" type="number" min="0.000001" step="any" value="5"></label><button type="button" class="btn small" data-transfer-tool="rod-pour">Guide measured pour</button><button type="button" class="btn soft small" data-transfer-tool="rod-mix">Stir destination contents</button>`;}
 return `<section class="bench-apparatus-popup simple-apparatus-popup transfer-tool-popup ${apparatusPopupPosition?'is-moved':'is-default'}" role="dialog" aria-label="${esc(benchVesselLabel(a))} transfer controls" style="${apparatusPopupPosition?`left:${apparatusPopupPosition.left}px;top:${apparatusPopupPosition.top}px;right:auto`:'right:8px;left:auto'}"><header class="apparatus-popup-head popup-drag-handle"><span><b>${esc(benchVesselLabel(a))}</b><small>Measured transfer tool</small></span><button type="button" data-apparatus-dismiss aria-label="Close apparatus panel">×</button></header><div class="apparatus-popup-content">${body}<p id="toolStatus" class="tool-status" role="status">${esc(note)}</p>${!['glassFunnel','glassRod'].includes(a.type)?'<button type="button" class="btn secondary small" data-transfer-tool="clean">Empty / clean tool</button>':''}${transformControlsHtml()}<a href="transfer-tools-reference.txt" target="_blank" rel="noopener">Transfer units &amp; preparation assumptions</a></div></section>`;
}
function transferMessage(a,text){if(a)a.toolMessage=text;const status=document.getElementById('toolStatus');if(status)status.textContent=text;const bench=document.getElementById('gasStatus');if(bench)bench.textContent=text;}
function transferCommit(a){a.phaseTint=null;a.preparedAtMark=false;a.solutionVolumeVerified=false;if(a.type==='separatoryFunnel'){a.settled=false;a.extractionDone=false;}const result=analyzeVessel(a);a.generatedGas=result.gas||null;a.gasTrapped=false;}
function transferMoveMass(source,target,mass){if(!Number.isFinite(mass)||mass<=0)return 'Enter a finite, positive mass in grams.';if(!source||!source.c||!transferDry(source.c))return 'Choose an available dry solid.';if(!target||!(acceptsSolid(target.type)||target.type==='volumetricFlask'||target.type==='spatula'))return 'Choose a compatible solid-receiving vessel.';if(Number(source.a.volume)>1e-12)return 'This is a wet mixture. Use a separated dry solid for a spatula transfer, or transfer the mixture as a liquid.';if(source.a.id===target.id)return 'Choose a different receiver.';if(mass>Number(source.c.mass)+1e-12)return 'Requested mass exceeds the available solid.';
 const moved={...source.c,mass:Number(Math.min(mass,Number(source.c.mass)).toPrecision(14)),volume:0};source.c.mass=Number((Number(source.c.mass)-moved.mass).toPrecision(14));if(source.c.mass<1e-12)source.a.contents.splice(source.index,1);transferAddDryItem(target,moved);target.mixed=target.contents.some(c=>c.type==='potassiumMetal')&&target.contents.some(c=>c.type==='water');transferCommit(target);return '';
}
function transferRouteFunnel(sourceId,targetId,amount){const f=apparatus.find(x=>x.id===targetId&&x.type==='glassFunnel');if(!f)return null;const target=apparatus.find(x=>x.id===f.funnelTargetId);if(!target||!transferToolIsVessel(target))return 'Attach the funnel to a receiving vessel first.';if(sourceId===target.id)return 'The source cannot be the flask underneath the funnel.';const error=pourLiquid(sourceId,target.id,amount);if(!error){selectedApp=f.id;redrawBench();transferMessage(f,`Transferred ${Number(amount).toPrecision(6)} mL through the funnel into ${benchVesselLabel(target)}. The source inventory was reduced.`);}return error;
}
function transferSyncFunnel(){const box=document.getElementById('benchCanvas')?.getBoundingClientRect();if(!box?.height)return;for(const f of apparatus.filter(x=>x.type==='glassFunnel'&&x.funnelTargetId)){const target=apparatus.find(x=>x.id===f.funnelTargetId);if(!target||!transferIsUpright(target)){f.funnelTargetId=null;f.toolMessage='Funnel detached. Attach it to an upright receiving vessel.';continue;}f.x=target.x;f.y=Math.max(1,Number(target.y)-55*(Number(target.scale)||100)/100/box.height*100);f.scale=target.scale||100;f.rotation=0;}}
function transferNormalizeEntries(items,entries){const V=items.reduce((s,c)=>s+(Number(c.volume)||0)/1000,0);return entries.map(e=>{if(!e.solidStock||!e.solidDissolved||!(V>0))return e;const n=Number(e.mass)/Number(e.solidMolarMass);return {...e,n,c:n/V};});}
function transferPreparationControls(a){const solids=(a.contents||[]).filter(c=>c.solidStock);if(!solids.length)return '';const V=Number(a.volume)||0;return `<section class="tool-preparation"><b>Preparation from measured solid</b>${solids.map(c=>`<p>${esc(c.reagent)} · ${Number(c.mass).toPrecision(5)} g${c.solidDissolved&&V>0?' · '+(Number(c.mass)/Number(c.solidMolarMass)/(V/1000)).toPrecision(5)+' mol/L':''}${c.solidDissolved?' · dissolved':' · undissolved'}</p>`).join('')}<button type="button" class="btn soft small" data-transfer-tool="dissolve">Mix to dissolve measured solid</button>${a.type==='volumetricFlask'?'<button type="button" class="btn small" data-transfer-tool="make-mark">Add distilled water to calibration mark</button>':''}<small>${a.preparedAtMark?'Final solution volume was set at the flask calibration mark.':'Before making to the mark, concentration is an estimate using the displayed volume; dissolution volume changes are not modeled.'} Dilute aqueous reference preparations only (≤ 1 M per solute); no saturation or dissolution-rate prediction.</small></section>`;}
function transferDissolve(a){const solids=(a.contents||[]).filter(c=>c.solidStock),V=Number(a.volume)/1000;if(!solids.length||!(V>0)||!a.contents.some(c=>c.type==='water'&&c.volume>0))return 'Add distilled water before dissolving the weighed solid.';if(a.contents.some(c=>!c.solidStock&&c.type!=='water'))return 'Use a fresh solid-and-water preparation. Dissolution into other reagent mixtures is outside this preparation model.';const totals=new Map();for(const c of solids){const n=Number(c.mass)/Number(c.solidMolarMass);totals.set(c.formula,(totals.get(c.formula)||0)+n);}if([...totals.values()].some(n=>!Number.isFinite(n)||n/V>1))return 'Add more water: this preparation model supports up to 1 mol/L of each solute.';if(a.type==='volumetricFlask'&&a.volume>=transferCap(a)&&solids.some(c=>!c.solidDissolved))return 'Start dissolving below the final calibration mark. A flask filled with solvent before the solid is dissolved does not define an accurate final solution volume.';if(solids.every(c=>c.solidDissolved)){a.mixed=true;return '';}for(const c of solids)c.solidDissolved=true;a.mixed=true;transferCommit(a);return '';}
function transferToolAction(action,a){const value=id=>document.getElementById(id)?.value,number=id=>Number(value(id)),receiver=()=>apparatus.find(x=>x.id===value('toolReceiver'));let error='',message='';if(value('toolReceiver'))a.toolReceiverId=value('toolReceiver');if(value('toolIndicator')!=null)a.toolIndicator=value('toolIndicator');if(value('toolDrops')!=null)a.toolDrops=number('toolDrops');if(value('toolDropSize')!=null)a.toolDropSize=number('toolDropSize');
 if(action==='pick-solid-source'){transferPickingSolidFor=transferPickingSolidFor===a.id?null:a.id;document.getElementById('benchCanvas')?.classList.toggle('tool-picking-source',!!transferPickingSolidFor);redrawBench();transferMessage(a,transferPickingSolidFor?'Click the beaker or vessel containing the dry solid.':'Source selection cancelled.');return;}
 if(action==='place-bench-solid'){const stock=transferSolidStocks[Number(value('benchSolidStock'))],mass=number('benchSolidMass');if(!acceptsSolid(a.type)||!stock||!Number.isFinite(mass)||mass<=0)error='Choose a reference solid, a finite positive mass, and a compatible vessel.';else{transferAddDryItem(a,transferMakeSolid(stock,mass));a.mixed=false;transferCommit(a);transferLastSolidSourceId=a.id;message=`Placed ${mass} g ${stock.name} in ${benchVesselLabel(a)}. Select a spatula to take a measured portion from this vessel.`;}}
 if(action!=='pick-solid-source'){transferPickingSolidFor=null;document.getElementById('benchCanvas')?.classList.remove('tool-picking-source');}if(action==='inspect-receiver'){const target=receiver();if(!target){transferMessage(a,'Choose a destination vessel first.');return;}selectedApp=target.id;benchPopupHiddenFor=null;redrawBench();return;}
 if(action==='pipette-load'){const source=apparatus.find(x=>x.id===value('toolPipetteSource')),fixed=a.type==='volumetricPipette',amount=fixed?transferCap(a):number('toolPipetteLoad');if(!source||!transferToolIsVessel(source))error='Choose a source solution.';else if(a.volume>1e-12)error='Empty / clean the pipette before loading a new aliquot.';else if(!Number.isFinite(amount)||amount<=0)error='Enter a finite, positive loading volume.';else{error=pourLiquid(source.id,a.id,amount);a.toolPipetteSource=source.id;message=`Loaded ${amount} mL from ${benchVesselLabel(source)}.`;}}
 if(action==='pipette-deliver'){const target=receiver(),amount=a.type==='volumetricPipette'?transferCap(a):number('toolPipetteDose');if(!target||!transferToolIsVessel(target))error='Choose a destination vessel.';else{error=pourLiquid(a.id,target.id,amount);message=`Delivered ${amount} mL into ${benchVesselLabel(target)}.`;}}
 if(action==='water-load'){const amount=number('toolWaterLoad');if(a.contents.some(c=>c.type!=='water'))error='Empty / clean this bottle before loading distilled water.';else if(!Number.isFinite(amount)||amount<=0||a.volume+amount>transferCap(a))error='Enter a positive volume within the wash bottle capacity.';else{const r=reagents.find(r=>r[2]==='water');a.contents.push({reagent:r[0],formula:r[1],type:'water',color:r[4],volume:amount,mass:0});a.volume=Number((Number(a.volume||0)+amount).toPrecision(14));message=`Loaded ${amount} mL distilled water.`;}}
 if(action==='water-rinse'){const target=receiver(),amount=number('toolWaterDose');if(!target||!transferToolIsVessel(target))error='Choose a destination vessel.';else if(a.contents.some(c=>c.type!=='water'))error='This bottle contains a non-water reagent; empty / clean it first.';else{error=pourLiquid(a.id,target.id,amount);message=`Added ${amount} mL distilled water to ${benchVesselLabel(target)}. Its liquid volume and dilution were updated.`;}}
 if(action==='rod-pour'){const source=apparatus.find(x=>x.id===value('toolRodSource')),target=receiver();if(!source||!target||!transferToolIsVessel(source)||!transferToolIsVessel(target))error='Choose source and receiving vessels.';else{error=pourLiquid(source.id,target.id,number('toolRodAmount'));a.toolRodSource=source.id;message=`Guided the measured pour into ${benchVesselLabel(target)}.`;}}
 if(action==='rod-mix'){const target=receiver();if(!target?.contents?.length)error='Choose a vessel containing material to mix.';else{target.mixed=true;transferCommit(target);message=`Stirred ${benchVesselLabel(target)}. ${analyzeVessel(target).note||''}`;}}
 if(action==='clean'){a.contents=[];a.volume=0;a.generatedGas=null;a.mixed=false;a.gasTrapped=false;a.phaseTint=null;a.preparedAtMark=false;a.toolSolidOriginId=null;message='Tool emptied and cleaned.';}
 if(action==='load-dropper'){const r=reagents[Number(value('toolIndicator'))],vol=number('toolLoadVolume');if(!r||!transferIndicatorTypes.has(r[2])||!Number.isFinite(vol)||vol<=0)error='Choose an indicator and a finite, positive load volume.';else if(a.contents.some(c=>c.reagent!==r[0]))error='Empty / clean this dropper before loading a different indicator.';else if((Number(a.volume)||0)+vol>transferCap(a)+1e-12)error='That exceeds the dropper capacity.';else{a.contents.push({reagent:r[0],formula:r[1],type:r[2],color:r[4],volume:vol,mass:0});a.volume=Number(((Number(a.volume)||0)+vol).toPrecision(14));message=`Loaded ${vol} mL ${r[0]}.`;}}
 if(action==='dispense'){const drops=number('toolDrops'),size=number('toolDropSize'),target=receiver(),dose=drops*size;if(!Number.isInteger(drops)||drops<1||!Number.isFinite(size)||size<.01||size>.1||Math.abs(size*100-Math.round(size*100))>1e-8)error='Enter a positive whole number of drops and a drop size from 0.01 to 0.10 mL in 0.01 mL steps.';else if(!target||!transferToolIsVessel(target))error='Choose a destination vessel.';else if(!a.contents.length||dose>Number(a.volume)+1e-12)error='The dropper does not contain enough indicator. Load it first.';else{error=pourLiquid(a.id,target.id,Number(dose.toPrecision(14)));message=`Dispensed ${drops} drop(s) ≈ ${Number(dose.toPrecision(8))} mL into ${benchVesselLabel(target)}.`;}}
 if(action==='load-spatula'){const source=transferSourceRecord(value('toolSource')),mass=number('toolLoadMass');if(a.contents.length)error='Empty / clean the spatula before loading another sample.';else if(!Number.isFinite(mass)||mass<=0)error='Enter a finite, positive weighed mass in grams.';else if(source?.stock&&a.toolSolidMode!=='stock')error='Choose Stock bottle explicitly to load new material; otherwise select an actual bench vessel.';else if(source?.stock){const s=source.stock;a.contents.push(transferMakeSolid(s,mass));a.toolSolidOriginId=null;message=`Loaded ${mass} g ${s.name}.`;}else{error=transferMoveMass(source,a,mass);if(!error){a.toolSolidSource=value('toolSource');a.toolSolidOriginId=source.a.id;}message=source?.a?`Loaded ${mass} g from ${benchVesselLabel(source.a)}; its remaining solid is ${(source.a.contents||[]).filter(transferDry).reduce((sum,c)=>sum+Number(c.mass),0).toPrecision(5)} g.`:'Choose a dry solid already on the bench.';}}
 if(action==='spatula-transfer'){let target=receiver();if(target?.type==='volumetricFlask'&&!apparatus.some(f=>f.type==='glassFunnel'&&f.funnelTargetId===target.id))error='Attach a glass funnel to this volumetric flask before transferring solid through its narrow neck.';else{error=transferMoveMass({a,c:a.contents[0],index:0},target,number('toolTransferMass'));message=target?`Transferred ${Number(number('toolTransferMass').toPrecision(8))} g into ${benchVesselLabel(target)}${target.type==='volumetricFlask'?' through its funnel':''}. ${a.contents.reduce((sum,c)=>sum+(Number(c.mass)||0),0).toPrecision(5)} g remains on the spatula.`:'';}}
 if(action==='attach'){const target=receiver();if(!target||!transferToolIsVessel(target))error='Select a compatible receiving flask or vessel.';else if(!transferIsUpright(target))error='Return the receiving vessel upright before attaching the funnel.';else if(apparatus.some(f=>f.id!==a.id&&f.funnelTargetId===target.id))error='This vessel already has an attached funnel.';else{a.funnelTargetId=target.id;message=`Funnel attached to ${benchVesselLabel(target)}.`;}}
 if(action==='detach'){a.funnelTargetId=null;message='Funnel detached.';}
 if(action==='funnel-transfer'){const target=apparatus.find(x=>x.id===a.funnelTargetId),source=value('toolSource')||'',amount=number('toolFunnelAmount');if(!target)error='Attach the funnel to a receiving vessel first.';else if(!source)error='Choose a source vessel or a loaded spatula.';else if(!Number.isFinite(amount)||amount<=0)error='Enter a finite, positive transfer amount.';else if(source.startsWith('liq:')){error=transferRouteFunnel(source.slice(4),a.id,amount)||'';message=`Transferred ${amount} mL through the funnel into ${benchVesselLabel(target)}.`;}else{error=transferMoveMass(transferSourceRecord(source),target,amount);message=`Transferred ${amount} g through the funnel into ${benchVesselLabel(target)}.`;}}
 if(action==='dissolve'){error=transferDissolve(a);message='Measured solid dissolved in the aqueous reference preparation. Moles are calculated from its weighed mass and molar mass.';}
 if(action==='make-mark'){if(a.type!=='volumetricFlask')error='Use a volumetric flask for a calibrated final volume.';else if(apparatus.some(f=>f.funnelTargetId===a.id))error='Detach the funnel before making the solution to the mark.';else if(!a.contents.some(c=>c.solidStock)||a.contents.some(c=>c.solidStock&&!c.solidDissolved))error='Dissolve all weighed solid before making to the mark.';else if(a.volume>transferCap(a)||a.volume===transferCap(a)&&!a.preparedAtMark)error='A full or overfilled flask cannot be corrected by adding water. Dissolve below the mark, then make a fresh preparation to the final volume.';else{const extra=transferCap(a)-Number(a.volume),water=reagents.findIndex(r=>r[2]==='water');if(extra>1e-12&&water>=0)addReagentToVessel(a,water,extra);a.volume=transferCap(a);a.preparedAtMark=true;a.solutionVolumeVerified=true;a.mixed=true;message=`Final solution volume set to ${a.volume} mL at the calibration mark. Mix thoroughly.`;}}
 selectedApp=a.id;if(!error){redrawBench();if(typeof persistWorkspace==='function')persistWorkspace();}transferMessage(a,error||message);
}
document.addEventListener('pointerdown',event=>{const target=event.target,app=target.closest?.('[data-app],[data-new]');if(transferPickingSolidFor){const tool=apparatus.find(a=>a.id===transferPickingSolidFor);if(app?.dataset.app&&tool){event.preventDefault();event.stopImmediatePropagation();const source=apparatus.find(a=>a.id===app.dataset.app),record=source&&transferBenchSolidSources(tool).find(row=>row.a.id===source.id);if(!record){transferMessage(tool,'This vessel has no available dry solid. Choose a vessel containing a weighed solid, not a solution or wet precipitate.');return;}tool.toolSolidMode='bench';tool.toolSolidSource=record.value;tool.toolReceiverId=tool.toolReceiverId===source.id?null:tool.toolReceiverId;transferLastSolidSourceId=source.id;transferPickingSolidFor=null;document.getElementById('benchCanvas')?.classList.remove('tool-picking-source');selectedApp=tool.id;benchPopupHiddenFor=null;redrawBench();transferMessage(tool,`Source selected: ${benchVesselLabel(source)} · ${record.c.mass} g ${record.c.reagent}.`);if(typeof persistWorkspace==='function')persistWorkspace();return;}if(!target.closest?.('.transfer-tool-popup')||target.closest?.('[data-apparatus-dismiss]')){transferPickingSolidFor=null;document.getElementById('benchCanvas')?.classList.remove('tool-picking-source');}}if(!app)return;const before=selectedEquipment();if(transferToolIsVessel(before))transferLastReceiverId=before.id;if(before&&before.type!=='spatula'&&!(Number(before.volume)>1e-12)&&before.contents?.some(transferDry)){transferLastSolidSourceId=before.id;const tool=apparatus.find(a=>a.id===app.dataset.app&&a.type==='spatula');if(tool&&!tool.contents?.length){const row=transferBenchSolidSources(tool).find(r=>r.a.id===before.id);tool.toolSolidMode='bench';tool.toolSolidSource=row?.value;}}},true);
document.addEventListener('change',event=>{const a=selectedEquipment();if(!a)return;if(event.target.id==='toolSolidMode'){a.toolSolidMode=event.target.value;transferPickingSolidFor=null;document.getElementById('benchCanvas')?.classList.remove('tool-picking-source');redrawBench();return;}if(event.target.id==='toolReceiver')a.toolReceiverId=event.target.value;if(event.target.id==='toolIndicator')a.toolIndicator=event.target.value;if(event.target.id==='toolSource'){if(a.type==='spatula'){transferPickingSolidFor=null;document.getElementById('benchCanvas')?.classList.remove('tool-picking-source');if(event.target.value.startsWith('stock:'))a.toolSolidStock=Number(event.target.value.split(':')[1]);else a.toolSolidSource=event.target.value;redrawBench();return;}const label=document.getElementById('toolAmountLabel');if(label)label.textContent=event.target.value.startsWith('liq:')?'Volume to transfer (mL)':'Mass to transfer (g)';}});
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-transfer-tool]');if(!button)return;const a=selectedEquipment();if(a)transferToolAction(button.dataset.transferTool,a);});

function transferShelfIcon(x){return x[4]==="Transfer"||["dropper","volumetricPipette","graduatedPipette"].includes(x[0])?equipSvg(x[0],0,x[3],"#f7faf8","transfer-shelf"):x[2];}

function transferIsUpright(a){const r=((Number(a.rotation)||0)%360+360)%360;return Math.min(r,360-r)<=2;}
function transferToolPlacement(type){if(!['dropper','spatula','glassFunnel','volumetricPipette','graduatedPipette','washBottle','glassRod'].includes(type))return [48+Math.random()*8,42+Math.random()*8];const box=document.getElementById('benchCanvas')?.getBoundingClientRect(),w=box?.width||700,h=box?.height||380;for(const y of [8,40,68])for(const x of [8,30,52,74])if(x+80/w*100<=100&&y+92/h*100<=100&&!apparatus.some(a=>Math.abs(Number(a.x)-x)<92/w*100&&Math.abs(Number(a.y)-y)<100/h*100))return [x,y];return [8,8];}

function transferDestinationLabel(a){if(a.type==="glassFunnel"){const target=apparatus.find(x=>x.id===a.funnelTargetId);return esc(benchVesselLabel(a))+(target?" → "+esc(benchVesselLabel(target)):" · attach a receiver first");}return esc(benchVesselLabel(a))+" · "+Number(a.volume||0).toFixed(2)+" / "+transferCap(a)+" mL";}
